import 'package:flutter/material.dart';
class FloatingControlButton extends StatelessWidget { const FloatingControlButton({super.key, required this.onPressed, this.active = true, this.tooltip = 'إيقاف التتبع'}); final VoidCallback onPressed; final bool active; final String tooltip; @override Widget build(BuildContext context) { final scheme = Theme.of(context).colorScheme; return FloatingActionButton.extended(heroTag: 'newvision-floating-control', onPressed: onPressed, tooltip: tooltip, backgroundColor: active ? scheme.errorContainer : scheme.surfaceContainerHighest, foregroundColor: active ? scheme.onErrorContainer : scheme.onSurfaceVariant, elevation: 6, icon: Icon(active ? Icons.stop_rounded : Icons.play_arrow_rounded), label: Text(active ? 'إيقاف' : 'بدء')); } }
